class Solution:
    def strangePrinter(self, s: str) -> int:
        def dfs(l, r):
            if l > r:
                return 0
            ans = dfs(l, r - 1) + 1
            for mid in range(l, r):
                if s[mid] == s[r]:
                    ans = min(ans, dfs(l, mid) + dfs(mid + 1, r - 1))
            return ans
        return dfs(0, len(s) - 1)

